import{_ as a,o,c as r,a2 as n}from"./chunks/framework.DpXDHk3d.js";const c=JSON.parse('{"title":"13.3 常用安全用具与绝缘防护","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/13-chapter-13-an-quan-zuo-ye-cao-zuo-gui-fan/13-3-chang-yong-an-quan-yong-ju-yu-jue-yuan-fang-hu.md","filePath":"electrician/low-voltage-electrician/13-chapter-13-an-quan-zuo-ye-cao-zuo-gui-fan/13-3-chang-yong-an-quan-yong-ju-yu-jue-yuan-fang-hu.md","lastUpdated":1793096070000}'),l={name:"electrician/low-voltage-electrician/13-chapter-13-an-quan-zuo-ye-cao-zuo-gui-fan/13-3-chang-yong-an-quan-yong-ju-yu-jue-yuan-fang-hu.md"};function e(i,t,s,d,u,g){return o(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="_13-3-常用安全用具与绝缘防护" tabindex="-1">13.3 常用安全用具与绝缘防护 <a class="header-anchor" href="#_13-3-常用安全用具与绝缘防护" aria-label="Permalink to &quot;13.3 常用安全用具与绝缘防护&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>安全用具是电工的&quot;护身符&quot;:绝缘手套、绝缘鞋、绝缘垫,还有验电器、安全带、安全帽。这一节分清&quot;绝缘安全用具&quot;和&quot;一般防护用具&quot;,记住保管与检验要求。</p><h2 id="一、安全用具的分类" tabindex="-1">一、安全用具的分类 <a class="header-anchor" href="#一、安全用具的分类" aria-label="Permalink to &quot;一、安全用具的分类&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类别</th><th>用具</th><th>作用</th></tr></thead><tbody><tr><td><strong>绝缘安全用具</strong></td><td>绝缘手套、绝缘鞋(靴)、绝缘垫、绝缘台、绝缘棒(令克棒)</td><td>隔离人体与带电体,直接防止触电</td></tr><tr><td><strong>一般防护用具</strong></td><td>安全帽、安全带、护目镜、验电器</td><td>防坠落、防砸、验电等</td></tr><tr><td><strong>辅助安全用具</strong></td><td>绝缘手套、绝缘鞋等(配合基本用具用)</td><td>加强绝缘保护</td></tr></tbody></table><blockquote><p>💡 通俗理解:<strong>绝缘用具是&quot;防触电的盔甲&quot;,一般防护用具是&quot;防摔防砸的盔甲&quot;</strong>。</p></blockquote><h2 id="二、常用绝缘安全用具-重点" tabindex="-1">二、常用绝缘安全用具(重点) <a class="header-anchor" href="#二、常用绝缘安全用具-重点" aria-label="Permalink to &quot;二、常用绝缘安全用具(重点)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>用具</th><th>用途</th><th>要点</th></tr></thead><tbody><tr><td><strong>绝缘手套</strong></td><td>低压带电作业、操作高压设备(辅助)</td><td>用前检查有无破损、漏气,套在衣袖外</td></tr><tr><td><strong>绝缘鞋(靴)</strong></td><td>站地操作时隔离地电位</td><td>干燥、无破损,穿前检查</td></tr><tr><td><strong>绝缘垫(绝缘台)</strong></td><td>铺在脚下,站上去操作</td><td>保持清洁干燥,无老化裂纹</td></tr><tr><td><strong>绝缘棒(验电器杆)</strong></td><td>操作高压开关、拉合隔离刀闸</td><td>用于高压,长度足够,干燥</td></tr></tbody></table><blockquote><p>⚠️ 判断题常考:使用绝缘手套前要检查<strong>有无破损、漏气(充气检查)</strong>;绝缘用具要保持<strong>干燥、清洁</strong>。</p></blockquote><h2 id="三、验电器-试电笔-验电笔" tabindex="-1">三、验电器(试电笔/验电笔) <a class="header-anchor" href="#三、验电器-试电笔-验电笔" aria-label="Permalink to &quot;三、验电器(试电笔/验电笔)&quot;">​</a></h2><ul><li>低压验电用<strong>试电笔(测电笔)</strong>,氖泡发光说明带电;</li><li>高压验电用<strong>高压验电器</strong>;</li><li>使用前<strong>先在有电设备上验证</strong>完好(13.2 节讲过);</li><li>试电笔测电时,手指要接触<strong>笔尾金属体</strong>,氖泡亮表示有电。</li></ul><blockquote><p>⚠️ 判断题常考:试电笔使用时,手指要接触笔尾的<strong>金属笔帽</strong>,氖泡发光表示带电。</p></blockquote><h2 id="四、一般防护用具" tabindex="-1">四、一般防护用具 <a class="header-anchor" href="#四、一般防护用具" aria-label="Permalink to &quot;四、一般防护用具&quot;">​</a></h2><ul><li><strong>安全帽</strong>:进入作业现场必须戴,防砸伤;</li><li><strong>安全带</strong>:登高(爬杆、登梯)作业必须系,<strong>高挂低用</strong>;</li><li><strong>护目镜</strong>:切割、打磨、带电操作时防异物、防弧光。</li></ul><h2 id="五、安全用具的保管与检验" tabindex="-1">五、安全用具的保管与检验 <a class="header-anchor" href="#五、安全用具的保管与检验" aria-label="Permalink to &quot;五、安全用具的保管与检验&quot;">​</a></h2><ul><li>用具<strong>专人保管、定点存放</strong>,不被油污、潮湿、高温破坏;</li><li>绝缘用具<strong>定期试验</strong>(绝缘手套、绝缘靴按规定周期做耐压试验),试验不合格<strong>报废</strong>;</li><li>使用前<strong>外观检查</strong>:有无破损、裂纹、老化、脏污;</li><li>不把绝缘用具当普通工具乱用、乱放。</li></ul><blockquote><p>⚠️ 判断题常考:<strong>绝缘安全用具要定期做耐压试验</strong>,试验合格的才可使用;发现破损立即停用。</p></blockquote><h2 id="六、考点提示" tabindex="-1">六、考点提示 <a class="header-anchor" href="#六、考点提示" aria-label="Permalink to &quot;六、考点提示&quot;">​</a></h2><ul><li>✅ 绝缘用具:手套、鞋、垫、台、棒——防触电。</li><li>✅ 一般防护:安全帽、安全带、护目镜——防摔防砸。</li><li>✅ 试电笔:手指接触笔尾金属,氖泡亮=带电;先验证后使用。</li><li>✅ 绝缘用具<strong>定期耐压试验</strong>,用前检查破损。</li><li>⚠️ 易混点:验电器(试电笔)是&quot;验有没有电&quot;的工具,不是绝缘防护用具。</li></ul><h2 id="七、本节小结" tabindex="-1">七、本节小结 <a class="header-anchor" href="#七、本节小结" aria-label="Permalink to &quot;七、本节小结&quot;">​</a></h2><ul><li>安全用具分绝缘防护和一般防护两大类。</li><li>试电笔验电,手指碰笔尾金属,氖泡亮为带电。</li><li>绝缘用具定期试验、用前检查、干燥保管。</li></ul><h2 id="八、自测练习" tabindex="-1">八、自测练习 <a class="header-anchor" href="#八、自测练习" aria-label="Permalink to &quot;八、自测练习&quot;">​</a></h2><ol><li>(判断)使用试电笔时,手指应接触笔尾金属体,氖泡发光表示带电。( )</li><li>(单选)下列属于绝缘安全用具的是()。 A. 安全帽　B. 绝缘手套　C. 安全带　D. 护目镜</li><li>(判断)绝缘手套使用前应检查有无破损、漏气。( )</li><li>(单选)登高作业时,应正确使用()。 A. 安全带　B. 绝缘垫　C. 试电笔　D. 接地线</li><li>(判断)绝缘安全用具应定期进行耐压试验,不合格的禁止使用。( )</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>√</strong>。手指接触笔尾金属体,氖泡亮表示带电。</li><li><strong>B</strong>。绝缘手套是绝缘安全用具。</li><li><strong>√</strong>。检查破损、漏气是使用前提。</li><li><strong>A</strong>。登高用安全带。</li><li><strong>√</strong>。定期耐压试验,不合格停用。</li></ol></details>',24)])])}const q=a(l,[["render",e]]);export{c as __pageData,q as default};
